          const seriesData = [];
          const len = data.length;

          for(let i = 0; i < len; i++) {
              const row = data[i] as any;
              const val = row[key];
              if (val !== null && val !== undefined && row.distance !== undefined) {
                  seriesData.push([row.distance, val]);
              }
